#!/bin/bash
# Verifier entrypoint of a coding task: the reward stack, after Senior SWE-Bench. Generated by eval-harvest
# emit; do not edit by hand. Harbor runs it in the separate verifier container (ADR-4) after the agent
# stops, and reads only /logs/verifier/reward.json. The agent's tree arrives at /work/repo as an
# artifact, without .git; /work/base is the clean base that the verifier image built.
#
#   0. Save the agent's change.
#   1. Agent-written tests: do the agent's own tests pass on its fix, fail on base?  (reported)
#   2. Pre-written verifiers: the hidden tests and the existing test suite.         (gate)
#   3. Validation agent: tests adapted to the change, from the validation spec.       (gate)
#   4. Task rubric judge, taste judge, and patch bloat.                               (thresholds)
#   5. Aggregate.
#
# The agent's tests run first, on the agent's own tree, before stage 2 restores the base test files.
set -u
L=/logs/verifier
mkdir -p "$L"
: > "$L/stages.log"
stage() { echo "== $1" | tee -a "$L/stages.log"; }

# Harbor skips the artifact upload when the agent deleted its tree. That is a failure of the agent, not
# an invalid trial, so it scores 0 on every key.
if [ ! -d /work/repo ]; then
  stage "the agent's tree is missing: reward 0"
  printf '%s\n' '{"fix_reward": 0.0, "fix_correct": 0.0, "fix_fail_to_pass": 0.0, "fix_pass_to_pass": 0.0, "fix_existing_suite": 0.0, "fix_validation": 0.0, "fix_rubric": 0.0, "fix_bloat": 0.0, "fix_taste_relative": 0.0, "fix_taste_practice": 0.0}' > "$L/reward.json"
  exit 0
fi

# The reward stack runs with the system Python and the verifier's own boto3 directory, never with the
# Python environment of the repository (a setup step can put a virtual environment first on PATH).
VERIFIER_PYTHON=/usr/bin/python3
[ -x "$VERIFIER_PYTHON" ] || VERIFIER_PYTHON=python3
verifier_python() { PYTHONPATH=/opt/eval-harvest-verifier "$VERIFIER_PYTHON" "$@"; }

BASE=$(git -C /work/base rev-parse HEAD)
# The artifact has no .git (exclude = [".git"]). Give the agent's tree the base history, so its change is
# the difference from the base commit.
rm -rf /work/repo/.git
cp -a /work/base/.git /work/repo/.git
cd /work/repo || exit 0

stage "0. save the agent's change"
git config user.email verifier@localhost; git config user.name verifier
git add -A >/dev/null 2>&1
git -c core.hooksPath=/dev/null commit -q --no-verify -m "agent changes" >/dev/null 2>&1
AGENT=$(git rev-parse HEAD)
git diff "$BASE" "$AGENT" > "$L/agent.patch"
git diff --stat "$BASE" "$AGENT" > "$L/agent.stat"

cd /tests/lib || exit 0
stage "1. agent-written tests"
verifier_python agent_tests.py "$BASE" "$AGENT" >> "$L/stages.log" 2>&1
stage "2. pre-written verifiers"
verifier_python hidden_tests.py "$BASE" "$AGENT" 2>> "$L/hidden_tests.stderr" | tee -a "$L/stages.log"
stage "3. validation agent"
verifier_python validate.py 2>> "$L/validation.stderr" | tee -a "$L/stages.log"
stage "4. rubric judge, taste judge, patch bloat"
verifier_python judges.py rubric 2>> "$L/rubric.stderr" | tee -a "$L/stages.log"
verifier_python judges.py taste 2>> "$L/taste.stderr" | tee -a "$L/stages.log"
verifier_python judges.py bloat | tee -a "$L/stages.log"
stage "5. aggregate"
verifier_python aggregate.py | tee -a "$L/stages.log"
exit 0
